package auth

import (
	"encoding/base64"
	"errors"
	"fmt"
	"strings"
	"testing"
	"time"

	"github.com/mudler/hadron-desktop/agent/internal/api"
)

// ---------------------------------------------------------------------------
// Generate
// ---------------------------------------------------------------------------

func TestGenerate_UserPrefixAndPayload(t *testing.T) {
	bearer, digest, err := Generate(ClassUser)
	if err != nil {
		t.Fatalf("Generate: %v", err)
	}
	if !strings.HasPrefix(bearer, "hdn_u_") {
		t.Fatalf("bearer %q does not have hdn_u_ prefix", bearer)
	}
	checkBearerPayload(t, bearer, "hdn_u_")
	checkDigestMatches(t, bearer, digest)
}

func TestGenerate_AdminPrefixAndPayload(t *testing.T) {
	bearer, digest, err := Generate(ClassAdmin)
	if err != nil {
		t.Fatalf("Generate: %v", err)
	}
	if !strings.HasPrefix(bearer, "hdn_a_") {
		t.Fatalf("bearer %q does not have hdn_a_ prefix", bearer)
	}
	checkBearerPayload(t, bearer, "hdn_a_")
	checkDigestMatches(t, bearer, digest)
}

func TestGenerate_UnknownClassErrors(t *testing.T) {
	if _, _, err := Generate(Class("bogus")); err == nil {
		t.Fatal("expected error for unknown class")
	}
}

func TestGenerate_ProducesUniqueRandomBearers(t *testing.T) {
	seen := make(map[string]bool)
	const n = 500
	for i := 0; i < n; i++ {
		bearer, _, err := Generate(ClassUser)
		if err != nil {
			t.Fatalf("Generate: %v", err)
		}
		if seen[bearer] {
			t.Fatalf("duplicate bearer generated: %q", bearer)
		}
		seen[bearer] = true
	}
}

// checkBearerPayload asserts the bearer's payload decodes to exactly 32
// random bytes via unpadded base64url, as required for a fresh bearer.
func checkBearerPayload(t *testing.T, bearer, prefix string) {
	t.Helper()
	payload := strings.TrimPrefix(bearer, prefix)
	if strings.ContainsAny(payload, "=+/") {
		t.Fatalf("payload %q is not unpadded base64url (contains padding or non-url chars)", payload)
	}
	decoded, err := base64.RawURLEncoding.DecodeString(payload)
	if err != nil {
		t.Fatalf("payload %q is not valid unpadded base64url: %v", payload, err)
	}
	if len(decoded) != 32 {
		t.Fatalf("decoded payload has %d bytes, want 32", len(decoded))
	}
}

// checkDigestMatches asserts digest is "sha256:" + 64 lowercase hex chars
// derived from the complete bearer string (prefix included).
func checkDigestMatches(t *testing.T, bearer string, digest Digest) {
	t.Helper()
	if err := digest.Validate(); err != nil {
		t.Fatalf("digest %q failed format validation: %v", digest, err)
	}
	want := digestBearer(bearer)
	if digest != want {
		t.Fatalf("digest %q does not match sha256 of complete bearer, want %q", digest, want)
	}
}

// ---------------------------------------------------------------------------
// Digest format
// ---------------------------------------------------------------------------

func TestDigest_Validate(t *testing.T) {
	valid := digestBearer("hdn_u_anything")
	if err := valid.Validate(); err != nil {
		t.Fatalf("expected valid digest, got error: %v", err)
	}

	cases := map[string]Digest{
		"missing prefix":     Digest(strings.Repeat("a", 64)),
		"wrong prefix":       Digest("md5:" + strings.Repeat("a", 64)),
		"too short":          Digest("sha256:" + strings.Repeat("a", 63)),
		"too long":           Digest("sha256:" + strings.Repeat("a", 65)),
		"uppercase hex":      Digest("sha256:" + strings.Repeat("A", 64)),
		"non-hex characters": Digest("sha256:" + strings.Repeat("g", 64)),
		"empty":              Digest(""),
	}
	for name, d := range cases {
		t.Run(name, func(t *testing.T) {
			if err := d.Validate(); err == nil {
				t.Fatalf("expected validation error for %s (%q)", name, d)
			}
		})
	}
}

// ---------------------------------------------------------------------------
// RotationConfig / NewVerifier
// ---------------------------------------------------------------------------

func TestNewVerifier_RejectsOverlapLongerThan24h(t *testing.T) {
	now := time.Now()
	_, curDigest, _ := Generate(ClassUser)
	_, prevDigest, _ := Generate(ClassUser)

	cfg := RotationConfig{
		Current:            curDigest,
		Previous:           prevDigest,
		PreviousValidUntil: now.Add(24*time.Hour + time.Second),
	}
	if _, err := newVerifierAt(now, cfg, validAdminConfig(now)); err == nil {
		t.Fatal("expected error for rotation overlap longer than 24h")
	}
}

func TestNewVerifier_AcceptsOverlapUpTo24h(t *testing.T) {
	now := time.Now()
	_, curDigest, _ := Generate(ClassUser)
	_, prevDigest, _ := Generate(ClassUser)

	cfg := RotationConfig{
		Current:            curDigest,
		Previous:           prevDigest,
		PreviousValidUntil: now.Add(24 * time.Hour),
	}
	if _, err := newVerifierAt(now, cfg, validAdminConfig(now)); err != nil {
		t.Fatalf("expected 24h overlap to be accepted, got error: %v", err)
	}
}

func TestNewVerifier_RejectsInvalidCurrentDigest(t *testing.T) {
	cfg := RotationConfig{Current: Digest("not-a-digest")}
	if _, err := NewVerifier(cfg, validAdminConfig(time.Now())); err == nil {
		t.Fatal("expected error for malformed current digest")
	}
}

func TestNewVerifier_RejectsPreviousWithoutValidUntil(t *testing.T) {
	_, curDigest, _ := Generate(ClassUser)
	_, prevDigest, _ := Generate(ClassUser)
	cfg := RotationConfig{Current: curDigest, Previous: prevDigest}
	if _, err := NewVerifier(cfg, validAdminConfig(time.Now())); err == nil {
		t.Fatal("expected error when previous is set without previous_valid_until")
	}
}

func TestNewVerifier_RejectsValidUntilWithoutPrevious(t *testing.T) {
	_, curDigest, _ := Generate(ClassUser)
	cfg := RotationConfig{Current: curDigest, PreviousValidUntil: time.Now().Add(time.Hour)}
	if _, err := NewVerifier(cfg, validAdminConfig(time.Now())); err == nil {
		t.Fatal("expected error when previous_valid_until is set without previous")
	}
}

// validAdminConfig returns a minimally valid admin RotationConfig (current
// digest only, no rotation in progress) for tests that only care about the
// user-class configuration.
func validAdminConfig(_ time.Time) RotationConfig {
	_, digest, _ := Generate(ClassAdmin)
	return RotationConfig{Current: digest}
}

// ---------------------------------------------------------------------------
// Verify: malformed / wrong class
// ---------------------------------------------------------------------------

func TestVerify_RejectsMalformedTokens(t *testing.T) {
	now := time.Now()
	_, userDigest, _ := Generate(ClassUser)
	_, adminDigest, _ := Generate(ClassAdmin)
	v, err := newVerifierAt(now, RotationConfig{Current: userDigest}, RotationConfig{Current: adminDigest})
	if err != nil {
		t.Fatalf("newVerifierAt: %v", err)
	}

	cases := map[string]string{
		"empty string":            "",
		"no prefix":               "totallynotabearer",
		"unknown prefix":          "hdn_x_" + strings.Repeat("A", 43),
		"prefix only":             "hdn_u_",
		"invalid base64 char":     "hdn_u_" + strings.Repeat("A", 42) + "!",
		"padded base64":           "hdn_u_" + strings.Repeat("A", 42) + "=",
		"too short payload":       "hdn_u_" + strings.Repeat("A", 10),
		"too long payload":        "hdn_u_" + strings.Repeat("A", 60),
		"admin prefix short body": "hdn_a_AAAA",
	}
	for name, bearer := range cases {
		t.Run(name, func(t *testing.T) {
			if _, err := v.Verify(bearer, ClassUser); !errors.Is(err, ErrMalformedBearer) {
				t.Fatalf("Verify(%q) = %v, want ErrMalformedBearer", bearer, err)
			}
		})
	}
}

func TestVerify_RejectsWrongClass(t *testing.T) {
	now := time.Now()
	userBearer, userDigest, _ := Generate(ClassUser)
	_, adminDigest, _ := Generate(ClassAdmin)
	v, err := newVerifierAt(now, RotationConfig{Current: userDigest}, RotationConfig{Current: adminDigest})
	if err != nil {
		t.Fatalf("newVerifierAt: %v", err)
	}

	if _, err := v.Verify(userBearer, ClassAdmin); !errors.Is(err, ErrWrongClass) {
		t.Fatalf("Verify(user bearer, ClassAdmin) = %v, want ErrWrongClass", err)
	}

	adminBearer, _, _ := Generate(ClassAdmin)
	if _, err := v.Verify(adminBearer, ClassUser); !errors.Is(err, ErrWrongClass) {
		t.Fatalf("Verify(admin bearer, ClassUser) = %v, want ErrWrongClass", err)
	}
}

// ---------------------------------------------------------------------------
// Verify: current / previous acceptance and rotation expiry
// ---------------------------------------------------------------------------

func TestVerify_AcceptsCurrentDigest(t *testing.T) {
	now := time.Now()
	userBearer, userDigest, _ := Generate(ClassUser)
	_, adminDigest, _ := Generate(ClassAdmin)
	v, err := newVerifierAt(now, RotationConfig{Current: userDigest}, RotationConfig{Current: adminDigest})
	if err != nil {
		t.Fatalf("newVerifierAt: %v", err)
	}

	info, err := v.Verify(userBearer, ClassUser)
	if err != nil {
		t.Fatalf("Verify: %v", err)
	}
	if len(info.Scopes) != 1 || info.Scopes[0] != "hadron:user" {
		t.Fatalf("Scopes = %v, want [hadron:user]", info.Scopes)
	}
	wantUserID := string(userDigest)[len("sha256:") : len("sha256:")+16]
	if info.UserID != wantUserID {
		t.Fatalf("UserID = %q, want %q", info.UserID, wantUserID)
	}
	cred, ok := info.Extra["credential"].(Credential)
	if !ok {
		t.Fatalf("Extra[credential] is %T, want Credential", info.Extra["credential"])
	}
	if cred.Class() != ClassUser || cred.Bearer() != userBearer {
		t.Fatalf("credential = %+v, want class=user bearer=%q", cred, userBearer)
	}
}

func TestVerify_AcceptsAdminCurrentDigest(t *testing.T) {
	now := time.Now()
	_, userDigest, _ := Generate(ClassUser)
	adminBearer, adminDigest, _ := Generate(ClassAdmin)
	v, err := newVerifierAt(now, RotationConfig{Current: userDigest}, RotationConfig{Current: adminDigest})
	if err != nil {
		t.Fatalf("newVerifierAt: %v", err)
	}

	info, err := v.Verify(adminBearer, ClassAdmin)
	if err != nil {
		t.Fatalf("Verify: %v", err)
	}
	if len(info.Scopes) != 1 || info.Scopes[0] != "hadron:admin" {
		t.Fatalf("Scopes = %v, want [hadron:admin]", info.Scopes)
	}
}

func TestVerify_AcceptsUnexpiredPreviousDigest(t *testing.T) {
	now := time.Now()
	oldBearer, oldDigest, _ := Generate(ClassUser)
	_, newDigest, _ := Generate(ClassUser)
	_, adminDigest, _ := Generate(ClassAdmin)

	cfg := RotationConfig{
		Current:            newDigest,
		Previous:           oldDigest,
		PreviousValidUntil: now.Add(time.Hour),
	}
	v, err := newVerifierAt(now, cfg, RotationConfig{Current: adminDigest})
	if err != nil {
		t.Fatalf("newVerifierAt: %v", err)
	}

	if _, err := v.Verify(oldBearer, ClassUser); err != nil {
		t.Fatalf("Verify(old bearer) = %v, want success (previous unexpired)", err)
	}
}

func TestVerify_RejectsExpiredPreviousDigest(t *testing.T) {
	now := time.Now()
	oldBearer, oldDigest, _ := Generate(ClassUser)
	_, newDigest, _ := Generate(ClassUser)
	_, adminDigest, _ := Generate(ClassAdmin)

	cfg := RotationConfig{
		Current:            newDigest,
		Previous:           oldDigest,
		PreviousValidUntil: now.Add(time.Hour),
	}
	v, err := newVerifierAt(now, cfg, RotationConfig{Current: adminDigest})
	if err != nil {
		t.Fatalf("newVerifierAt: %v", err)
	}
	// Advance the verifier's clock past previous_valid_until.
	v.now = func() time.Time { return now.Add(2 * time.Hour) }

	if _, err := v.Verify(oldBearer, ClassUser); !errors.Is(err, ErrInvalidBearer) {
		t.Fatalf("Verify(expired old bearer) = %v, want ErrInvalidBearer", err)
	}
}

func TestVerify_RejectsUnknownBearer(t *testing.T) {
	now := time.Now()
	_, userDigest, _ := Generate(ClassUser)
	_, adminDigest, _ := Generate(ClassAdmin)
	v, err := newVerifierAt(now, RotationConfig{Current: userDigest}, RotationConfig{Current: adminDigest})
	if err != nil {
		t.Fatalf("newVerifierAt: %v", err)
	}

	stranger, _, _ := Generate(ClassUser)
	if _, err := v.Verify(stranger, ClassUser); !errors.Is(err, ErrInvalidBearer) {
		t.Fatalf("Verify(unknown bearer) = %v, want ErrInvalidBearer", err)
	}
}

// ---------------------------------------------------------------------------
// Non-short-circuit comparison
// ---------------------------------------------------------------------------

func TestVerify_ComparesEveryConfiguredDigest_NoMatch(t *testing.T) {
	now := time.Now()
	_, curDigest, _ := Generate(ClassUser)
	_, prevDigest, _ := Generate(ClassUser)
	_, adminDigest, _ := Generate(ClassAdmin)

	cfg := RotationConfig{
		Current:            curDigest,
		Previous:           prevDigest,
		PreviousValidUntil: now.Add(time.Hour),
	}
	v, err := newVerifierAt(now, cfg, RotationConfig{Current: adminDigest})
	if err != nil {
		t.Fatalf("newVerifierAt: %v", err)
	}

	stranger, _, _ := Generate(ClassUser)

	calls := 0
	testCompareHook = func() { calls++ }
	defer func() { testCompareHook = nil }()

	if _, err := v.Verify(stranger, ClassUser); !errors.Is(err, ErrInvalidBearer) {
		t.Fatalf("Verify(stranger) = %v, want ErrInvalidBearer", err)
	}
	if calls != 2 {
		t.Fatalf("compareDigest invoked %d times, want 2 (current and previous both compared even though neither matched)", calls)
	}
}

func TestVerify_ComparesEveryConfiguredDigest_MatchOnCurrentStillComparesPrevious(t *testing.T) {
	now := time.Now()
	curBearer, curDigest, _ := Generate(ClassUser)
	_, prevDigest, _ := Generate(ClassUser)
	_, adminDigest, _ := Generate(ClassAdmin)

	cfg := RotationConfig{
		Current:            curDigest,
		Previous:           prevDigest,
		PreviousValidUntil: now.Add(time.Hour),
	}
	v, err := newVerifierAt(now, cfg, RotationConfig{Current: adminDigest})
	if err != nil {
		t.Fatalf("newVerifierAt: %v", err)
	}

	calls := 0
	testCompareHook = func() { calls++ }
	defer func() { testCompareHook = nil }()

	if _, err := v.Verify(curBearer, ClassUser); err != nil {
		t.Fatalf("Verify(current bearer) = %v, want success", err)
	}
	// The verifier must not short-circuit: even though the bearer matched
	// on the very first (current) comparison, the previous digest is still
	// compared, so the number and timing of comparisons performed does not
	// reveal which candidate (if any) matched.
	if calls != 2 {
		t.Fatalf("compareDigest invoked %d times, want 2 (must not short-circuit after matching current)", calls)
	}
}

func TestVerify_ComparesEveryConfiguredDigest_MatchOnPrevious(t *testing.T) {
	now := time.Now()
	oldBearer, oldDigest, _ := Generate(ClassUser)
	_, newDigest, _ := Generate(ClassUser)
	_, adminDigest, _ := Generate(ClassAdmin)

	cfg := RotationConfig{
		Current:            newDigest,
		Previous:           oldDigest,
		PreviousValidUntil: now.Add(time.Hour),
	}
	v, err := newVerifierAt(now, cfg, RotationConfig{Current: adminDigest})
	if err != nil {
		t.Fatalf("newVerifierAt: %v", err)
	}

	calls := 0
	testCompareHook = func() { calls++ }
	defer func() { testCompareHook = nil }()

	if _, err := v.Verify(oldBearer, ClassUser); err != nil {
		t.Fatalf("Verify(old bearer) = %v, want success", err)
	}
	if calls != 2 {
		t.Fatalf("compareDigest invoked %d times, want 2", calls)
	}
}

// ---------------------------------------------------------------------------
// Credential: never leaks via Stringer/%v/%s formatting
// ---------------------------------------------------------------------------

func TestCredential_NeverLeaksRawBearerThroughFormatting(t *testing.T) {
	const secretBearer = "hdn_a_super-secret-value-do-not-log-me"
	cred := Credential{class: ClassAdmin, bearer: secretBearer}

	outputs := []string{
		fmt.Sprintf("%v", cred),
		fmt.Sprintf("%+v", cred),
		fmt.Sprintf("%#v", cred),
		fmt.Sprintf("%s", cred),
		fmt.Sprintln(cred),
	}
	for _, out := range outputs {
		if strings.Contains(out, secretBearer) {
			t.Fatalf("formatted output leaked raw bearer: %q", out)
		}
		if strings.Contains(out, "super-secret-value") {
			t.Fatalf("formatted output leaked bearer fragment: %q", out)
		}
	}

	// The accessor is the only sanctioned way to retrieve the raw bearer.
	if cred.Bearer() != secretBearer {
		t.Fatalf("Bearer() = %q, want %q", cred.Bearer(), secretBearer)
	}
	if cred.Class() != ClassAdmin {
		t.Fatalf("Class() = %q, want %q", cred.Class(), ClassAdmin)
	}
}

// ---------------------------------------------------------------------------
// Code: maps verify errors to stable api.ErrorCode values
// ---------------------------------------------------------------------------

func TestCode_MapsErrorsToAPICodes(t *testing.T) {
	cases := []struct {
		err  error
		want api.ErrorCode
	}{
		{nil, ""},
		{ErrMalformedBearer, api.CodeUnauthenticated},
		{ErrInvalidBearer, api.CodeUnauthenticated},
		{ErrWrongClass, api.CodeForbidden},
	}
	for _, c := range cases {
		if got := Code(c.err); got != c.want {
			t.Fatalf("Code(%v) = %q, want %q", c.err, got, c.want)
		}
	}
}

package main

import (
	"fmt"
	"strings"

	"github.com/charmbracelet/bubbles/spinner"
	"github.com/charmbracelet/bubbles/viewport"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
)

type lineMsg string
type doneMsg struct{ err error }

type action int

const (
	actionNone  action = iota
	actionShell        // on exit, main() should exec a rescue shell
)

type model struct {
	spin     spinner.Model
	vp       viewport.Model
	logs     *ring
	step     int
	showLogs bool
	failed   bool
	done     bool
	action   action
	ready    bool
	height   int
}

func newModel() model {
	s := spinner.New()
	s.Spinner = spinner.Line // ASCII (|/-\) — safe on the VT console font
	return model{spin: s, logs: newRing(2000)}
}

func (m model) Init() tea.Cmd { return m.spin.Tick }

func (m model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		// Reserve two rows of chrome, not one. The failure view is the tallest:
		// a halt banner above the viewport and a rescue hint below it. Sizing the
		// viewport to Height-1 makes that view Height+1 rows, and bubbletea's
		// renderer drops the *leading* overflow (standard_renderer.go: it keeps
		// the last r.height lines) — which silently ate the red "install halted"
		// banner, the one thing the user must see. See TestViewsFitTerminalHeight.
		m.height = msg.Height
		m.vp = viewport.New(msg.Width, msg.Height-2)
		m.vp.SetContent(m.logs.text())
		m.ready = true
		return m, nil

	case lineMsg:
		atBottom := m.ready && m.vp.AtBottom()
		m.logs.add(string(msg))
		m.step = AdvanceStep(string(msg), m.step)
		if m.ready {
			m.vp.SetContent(m.logs.text())
			if atBottom {
				m.vp.GotoBottom() // follow the tail unless the user scrolled up
			}
		}
		return m, nil

	case doneMsg:
		if msg.err != nil {
			m.failed = true
			m.showLogs = true // a failure without logs is useless
			if m.ready {
				m.vp.SetContent(m.logs.text())
				m.vp.GotoBottom()
			}
			return m, nil
		}
		m.done = true
		m.step = len(Steps) - 1
		return m, tea.Quit

	case tea.KeyMsg:
		return m.handleKey(msg)

	case spinner.TickMsg:
		var cmd tea.Cmd
		m.spin, cmd = m.spin.Update(msg)
		return m, cmd
	}
	return m, nil
}

func (m model) handleKey(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	if m.failed {
		if msg.String() == "s" {
			m.action = actionShell
			return m, tea.Quit
		}
		// A second way off the failure screen. bubbletea puts the tty in raw
		// mode, so ctrl+c arrives here as a key rather than SIGINT, and v1.3.10
		// installs no default quit binding — without this, 's' is the only exit
		// and a flaky VT keyboard would strand a failed install until a power
		// cycle. m.failed stays set, so runInstall still exits non-zero.
		if msg.String() == "ctrl+c" {
			return m, tea.Quit
		}
		var cmd tea.Cmd
		m.vp, cmd = m.vp.Update(msg) // allow scrolling the logs
		return m, cmd
	}
	if msg.String() == "l" {
		m.showLogs = !m.showLogs
		return m, nil
	}
	if m.showLogs {
		var cmd tea.Cmd
		m.vp, cmd = m.vp.Update(msg)
		return m, cmd
	}
	// Deliberately no quit key while installing: the disk is being written.
	return m, nil
}

// Tokyo Night styles, matching the boot splash so the handoff reads as one
// continuous machine. 16-color VGA palette only: this runs on the kernel VT
// (TERM=linux), where truecolor and 256-color values round to the wrong hue.
// 12 = bright blue, 14 = bright cyan, 8 = dark grey, 15 = white-hot,
// 9 = red (reserved for a real halt).
var (
	tnLogo  = lipgloss.NewStyle().Foreground(lipgloss.Color("12")).Bold(true)
	tnHot   = lipgloss.NewStyle().Foreground(lipgloss.Color("15")).Bold(true)
	tnDim   = lipgloss.NewStyle().Foreground(lipgloss.Color("8"))
	tnAcc   = lipgloss.NewStyle().Foreground(lipgloss.Color("14"))
	haltRed = lipgloss.NewStyle().Foreground(lipgloss.Color("9")).Bold(true)
)

// progressBar renders [####....] with a bright fill over a dim track.
func progressBar(pct, width int) string {
	if width < 1 {
		width = 1
	}
	if pct < 0 {
		pct = 0
	}
	if pct > 100 {
		pct = 100
	}
	fill := pct * width / 100
	return tnDim.Render("[") + tnAcc.Render(strings.Repeat("#", fill)) +
		tnDim.Render(strings.Repeat(".", width-fill)) + tnDim.Render("]")
}

// clampHeight drops trailing lines so s is at most height rows. bubbletea's
// renderer keeps the *last* height lines of whatever it is given, so an
// over-tall view loses its top — on the failure screen that is the halt banner.
// Truncating from the bottom instead keeps the banner and costs only a hint
// line. height <= 0 means we have not been told the terminal size yet.
func clampHeight(s string, height int) string {
	if height <= 0 {
		return s
	}
	lines := strings.Split(s, "\n")
	if len(lines) <= height {
		return s
	}
	return strings.Join(lines[:height], "\n")
}

func (m model) View() string { return clampHeight(m.view(), m.height) }

func (m model) view() string {
	if !m.ready {
		return "\n  " + tnDim.Render("waking the machine...")
	}
	if m.failed {
		return haltRed.Render("  install halted") + "\n" + m.vp.View() +
			// ctrl+c is advertised alongside 's' because it exists for the case
			// where 's' does not arrive — a real VT that swallows the keypress.
			// A user who cannot discover the alternative cannot use it.
			"\n  " + tnDim.Render("press 's' for a rescue shell · ctrl+c to exit")
	}
	if m.showLogs {
		return m.vp.View() + "\n  " + tnDim.Render("press 'l' to hide logs")
	}

	var b strings.Builder
	b.WriteString("\n")
	for _, l := range logo {
		b.WriteString("        " + tnLogo.Render(l) + "\n")
	}
	b.WriteString("\n")
	if m.done {
		b.WriteString("        " + tnHot.Render("system installed - rebooting...") + "\n")
	} else {
		b.WriteString("        " + tnHot.Render(m.spin.View()) + "  " +
			tnHot.Render(Steps[m.step].Name) + "...\n")
	}
	pct := Percent(m.step)
	b.WriteString("\n        " + progressBar(pct, 20) +
		tnDim.Render(fmt.Sprintf("  %3d%%", pct)) + "\n")
	b.WriteString("\n        " + tnDim.Render("press 'l' to show logs · do not power off") + "\n")
	return b.String()
}

// Package auth generates, verifies, and rotates the bearer credentials that
// authenticate every hadron-agent MCP request. It defines the two bearer
// classes (user and admin), the digest format credentials are stored in at
// rest, and a Verifier that accepts a bounded rotation window between a
// current and previous digest.
//
// This package is the security boundary for hadron-agent: the gateway (a
// later Phase-2 task) calls Verifier.Verify on every /mcp request, and the
// root-helper independently re-verifies the raw admin bearer before
// forwarding a privileged call. Bearer values must never be logged; see
// Credential for how that is enforced even under %v/%s formatting.
package auth

import (
	"crypto/rand"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/base64"
	"encoding/hex"
	"errors"
	"fmt"
	"strings"
	"time"

	sdkauth "github.com/modelcontextprotocol/go-sdk/auth"

	"github.com/mudler/hadron-desktop/agent/internal/api"
)

// ---------------------------------------------------------------------------
// Bearer classes
// ---------------------------------------------------------------------------

// Class identifies which of the two bearer classes a credential belongs to.
// The class is encoded in the bearer's prefix and is not secret: it only
// says what kind of credential this is, not whether it is valid.
type Class string

const (
	// ClassUser is the bearer class presented by ordinary MCP clients
	// (the Cua agent loop) and carries the "hadron:user" scope.
	ClassUser Class = "user"
	// ClassAdmin is the bearer class presented by the root-helper's
	// privileged callers and carries the "hadron:admin" scope.
	ClassAdmin Class = "admin"
)

const bearerRandomBytes = 32

var prefixByClass = map[Class]string{
	ClassUser:  "hdn_u_",
	ClassAdmin: "hdn_a_",
}

// scopeForClass returns the MCP scope string a successfully verified bearer
// of class grants.
func scopeForClass(class Class) string {
	if class == ClassAdmin {
		return "hadron:admin"
	}
	return "hadron:user"
}

// ---------------------------------------------------------------------------
// Digest
// ---------------------------------------------------------------------------

// Digest is a credential's at-rest representation: the literal string
// "sha256:" followed by exactly 64 lowercase hexadecimal characters (the
// hex-encoded SHA-256 sum of a complete bearer string, prefix included).
// Digests, unlike bearers, are safe to store in configuration and logs.
type Digest string

const (
	digestPrefix = "sha256:"
	digestHexLen = 64
)

// Validate reports whether d has the exact "sha256:<64 lowercase hex>"
// format. It does not check that d corresponds to any real bearer.
func (d Digest) Validate() error {
	s := string(d)
	if !strings.HasPrefix(s, digestPrefix) {
		return fmt.Errorf("auth: digest must start with %q", digestPrefix)
	}
	h := s[len(digestPrefix):]
	if len(h) != digestHexLen {
		return fmt.Errorf("auth: digest hex part must be %d characters, got %d", digestHexLen, len(h))
	}
	for _, r := range h {
		if (r < '0' || r > '9') && (r < 'a' || r > 'f') {
			return fmt.Errorf("auth: digest must be lowercase hex")
		}
	}
	return nil
}

// hex64 returns the 64 hex characters following the "sha256:" prefix.
// Callers must only call this on a Digest that has already passed
// Validate.
func (d Digest) hex64() string {
	return string(d)[len(digestPrefix):]
}

// digestBearer computes the at-rest Digest of a complete bearer string
// (prefix included).
func digestBearer(bearer string) Digest {
	sum := sha256.Sum256([]byte(bearer))
	return Digest(digestPrefix + hex.EncodeToString(sum[:]))
}

// ---------------------------------------------------------------------------
// Generate
// ---------------------------------------------------------------------------

// Generate creates a fresh bearer of the given class: "hdn_u_" or "hdn_a_"
// followed by 32 crypto/rand bytes encoded as unpadded base64url. It
// returns both the raw bearer (present this to the caller exactly once;
// never store it) and its Digest (store this).
func Generate(class Class) (bearer string, digest Digest, err error) {
	prefix, ok := prefixByClass[class]
	if !ok {
		return "", "", fmt.Errorf("auth: unknown bearer class %q", class)
	}
	buf := make([]byte, bearerRandomBytes)
	if _, err := rand.Read(buf); err != nil {
		return "", "", fmt.Errorf("auth: generate bearer: %w", err)
	}
	bearer = prefix + base64.RawURLEncoding.EncodeToString(buf)
	return bearer, digestBearer(bearer), nil
}

// parseBearerClass validates rawBearer's format (a known class prefix
// followed by exactly bearerRandomBytes of unpadded base64url) and, if
// valid, returns the class its prefix names. The prefix itself is public
// metadata, so matching it does not need to run in constant time; only the
// secret digest comparison in Verify does.
func parseBearerClass(rawBearer string) (Class, error) {
	for class, prefix := range prefixByClass {
		if !strings.HasPrefix(rawBearer, prefix) {
			continue
		}
		payload := strings.TrimPrefix(rawBearer, prefix)
		if !isWellFormedPayload(payload) {
			return "", ErrMalformedBearer
		}
		return class, nil
	}
	return "", ErrMalformedBearer
}

// isWellFormedPayload reports whether payload is exactly the unpadded
// base64url encoding of bearerRandomBytes random bytes.
func isWellFormedPayload(payload string) bool {
	if len(payload) != base64.RawURLEncoding.EncodedLen(bearerRandomBytes) {
		return false
	}
	decoded, err := base64.RawURLEncoding.DecodeString(payload)
	if err != nil {
		return false
	}
	return len(decoded) == bearerRandomBytes
}

// ---------------------------------------------------------------------------
// Credential (private payload carried in TokenInfo.Extra)
// ---------------------------------------------------------------------------

// Credential is the value Verify places in TokenInfo.Extra["credential"].
// It carries the class and the complete raw bearer so that only code that
// deliberately imports this package and calls Bearer() -- the root-helper
// proxy, which must forward the exact bearer upstream -- can retrieve the
// secret. Ordinary consumers of TokenInfo (Scopes, UserID) never need it.
//
// Fields are unexported so json.Marshal and any struct-literal comparison
// outside this package cannot touch the raw bearer. That alone is *not*
// sufficient to stop a leak through fmt: Go's default struct formatter
// prints unexported field values via reflection even though external
// packages cannot read them directly (verified: fmt.Sprintf("%v", struct{
// s string }{"secret"}) prints "secret"). The only way to stop that is to
// implement Stringer/GoStringer ourselves, so -- deliberately, and for that
// reason -- Credential implements both, returning a fixed redacted
// placeholder instead of the class/bearer, so %v, %s, %+v, %#v, and the
// Print family can never echo a bearer into a log line.
type Credential struct {
	class  Class
	bearer string
}

// Class reports which bearer class the credential belongs to.
func (c Credential) Class() Class { return c.class }

// Bearer returns the complete raw bearer string. Callers must never log,
// print, or otherwise format this value themselves; it exists solely so
// the root-helper proxy can forward the same bearer to the privileged
// upstream it authenticates.
func (c Credential) Bearer() string { return c.bearer }

// String implements fmt.Stringer with a fixed placeholder so %v/%s/%+v and
// the Print family never reveal the class or the raw bearer.
func (c Credential) String() string { return "auth.Credential{REDACTED}" }

// GoString implements fmt.GoStringer for the same reason, covering %#v.
func (c Credential) GoString() string { return "auth.Credential{REDACTED}" }

// ---------------------------------------------------------------------------
// Rotation configuration
// ---------------------------------------------------------------------------

// MaxRotationOverlap is the longest a Previous digest may remain valid
// after a RotationConfig is constructed. NewVerifier rejects any
// configuration whose overlap window exceeds it.
const MaxRotationOverlap = 24 * time.Hour

// RotationConfig configures the digests a Verifier accepts for one bearer
// class. Current is always accepted. Previous, if set, is accepted only
// until PreviousValidUntil, giving credential rotation a bounded overlap
// window instead of letting the old digest remain valid forever.
type RotationConfig struct {
	// Current is the digest of the presently active bearer for this
	// class. Required.
	Current Digest
	// Previous is the digest of the bearer being rotated out. Leave the
	// zero value ("") when no rotation is in progress.
	Previous Digest
	// PreviousValidUntil is the instant Previous stops being accepted.
	// Required when Previous is set; must not be set otherwise.
	PreviousValidUntil time.Time
}

// validate checks cfg for internal consistency, using now as the reference
// instant for the overlap-window bound.
func (cfg RotationConfig) validate(now time.Time) error {
	if err := cfg.Current.Validate(); err != nil {
		return fmt.Errorf("current: %w", err)
	}
	if cfg.Previous == "" {
		if !cfg.PreviousValidUntil.IsZero() {
			return errors.New("previous_valid_until set without previous")
		}
		return nil
	}
	if err := cfg.Previous.Validate(); err != nil {
		return fmt.Errorf("previous: %w", err)
	}
	if cfg.Previous == cfg.Current {
		return errors.New("previous must differ from current")
	}
	if cfg.PreviousValidUntil.IsZero() {
		return errors.New("previous set without previous_valid_until")
	}
	if overlap := cfg.PreviousValidUntil.Sub(now); overlap > MaxRotationOverlap {
		return fmt.Errorf("rotation overlap %s exceeds maximum %s", overlap, MaxRotationOverlap)
	}
	return nil
}

// ---------------------------------------------------------------------------
// Verify errors
// ---------------------------------------------------------------------------

var (
	// ErrMalformedBearer means the presented string is not a
	// syntactically valid bearer for either class (unknown prefix, or a
	// payload that is not exactly 32 bytes of unpadded base64url).
	ErrMalformedBearer = errors.New("auth: malformed bearer")
	// ErrWrongClass means the bearer is well-formed and of a known
	// class, but that class does not match the class the caller
	// required (a user bearer presented where admin was required, or
	// vice versa).
	ErrWrongClass = errors.New("auth: bearer class does not match required class")
	// ErrInvalidBearer means the bearer is well-formed and of the
	// required class, but its digest does not match any currently
	// accepted candidate (neither the current digest, nor an unexpired
	// previous digest).
	ErrInvalidBearer = errors.New("auth: bearer does not match any configured credential")
)

// Code maps an error returned by Verify to the stable api.ErrorCode the
// gateway should report in its response envelope. It returns "" for a nil
// error and api.CodeUnauthenticated for any error it does not specifically
// recognize, so a caller can always safely report *some* stable code.
func Code(err error) api.ErrorCode {
	switch {
	case err == nil:
		return ""
	case errors.Is(err, ErrWrongClass):
		return api.CodeForbidden
	default:
		return api.CodeUnauthenticated
	}
}

// ---------------------------------------------------------------------------
// Verifier
// ---------------------------------------------------------------------------

// Verifier holds the current rotation configuration for both bearer
// classes and verifies presented bearers against them.
type Verifier struct {
	user  RotationConfig
	admin RotationConfig
	now   func() time.Time
}

// NewVerifier constructs a Verifier from the user and admin rotation
// configurations. It rejects a configuration whose current digest is
// malformed, whose previous/previous_valid_until pairing is inconsistent,
// or whose rotation overlap window exceeds MaxRotationOverlap as measured
// from the moment NewVerifier is called.
func NewVerifier(user, admin RotationConfig) (*Verifier, error) {
	return newVerifierAt(time.Now(), user, admin)
}

// newVerifierAt is NewVerifier with an explicit reference instant, used by
// this package's own tests to exercise the rotation-overlap boundary and
// expiry behavior deterministically.
func newVerifierAt(now time.Time, user, admin RotationConfig) (*Verifier, error) {
	if err := user.validate(now); err != nil {
		return nil, fmt.Errorf("auth: user rotation config: %w", err)
	}
	if err := admin.validate(now); err != nil {
		return nil, fmt.Errorf("auth: admin rotation config: %w", err)
	}
	return &Verifier{user: user, admin: admin, now: time.Now}, nil
}

// configFor returns the RotationConfig governing class.
func (v *Verifier) configFor(class Class) RotationConfig {
	if class == ClassAdmin {
		return v.admin
	}
	return v.user
}

// testCompareHook, when non-nil, is invoked once per constant-time digest
// comparison performed inside Verify. It exists solely so this package's
// own tests can assert that every configured candidate digest is always
// compared -- current and, when configured, previous -- regardless of
// whether an earlier candidate already matched. Production code never sets
// it; it has no effect outside of _test.go files in this package.
var testCompareHook func()

// compareDigest reports, as 1 or 0, whether got and want are equal, using
// subtle.ConstantTimeCompare so the comparison time does not depend on
// where got and want first differ.
func compareDigest(got, want Digest) int {
	if testCompareHook != nil {
		testCompareHook()
	}
	return subtle.ConstantTimeCompare([]byte(got), []byte(want))
}

// Verify checks rawBearer against the Verifier's configured digests for
// requiredClass and, on success, returns an *sdkauth.TokenInfo carrying the
// scope for that class, a UserID derived from the digest, and a private
// Credential (class + raw bearer) in Extra["credential"].
//
// Once rawBearer's format and class prefix are confirmed (public
// properties of the string itself, so this part is not constant-time),
// verification hashes the complete bearer and compares the resulting
// digest against every currently configured candidate -- the class's
// current digest, and its previous digest if one is configured -- using
// subtle.ConstantTimeCompare. Both comparisons always run and their
// results are combined with bitwise OR/AND rather than an early return, so
// neither how many candidates are configured nor which one (if any)
// matched is observable from the number or timing of comparisons
// performed.
func (v *Verifier) Verify(rawBearer string, requiredClass Class) (*sdkauth.TokenInfo, error) {
	class, err := parseBearerClass(rawBearer)
	if err != nil {
		return nil, err
	}
	if class != requiredClass {
		return nil, ErrWrongClass
	}

	cfg := v.configFor(class)
	digest := digestBearer(rawBearer)

	// currentMatch and previousMatch are computed independently and both
	// constant-time digest comparisons always execute -- see the
	// non-short-circuit contract documented above.
	currentMatch := compareDigest(digest, cfg.Current)

	previousMatch := 0
	if cfg.Previous != "" {
		rawMatch := compareDigest(digest, cfg.Previous)
		unexpired := 0
		if !v.now().After(cfg.PreviousValidUntil) {
			unexpired = 1
		}
		previousMatch = rawMatch & unexpired
	}

	if currentMatch|previousMatch != 1 {
		return nil, ErrInvalidBearer
	}

	hex := digest.hex64()
	return &sdkauth.TokenInfo{
		Scopes: []string{scopeForClass(class)},
		UserID: hex[:16],
		Extra: map[string]any{
			"credential": Credential{class: class, bearer: rawBearer},
		},
	}, nil
}

package main

import "testing"

func TestRingKeepsMostRecentLines(t *testing.T) {
	r := newRing(3)
	for _, s := range []string{"a", "b", "c", "d", "e"} {
		r.add(s)
	}
	got := r.lines()
	if len(got) != 3 {
		t.Fatalf("len = %d, want 3", len(got))
	}
	want := []string{"c", "d", "e"}
	for i := range want {
		if got[i] != want[i] {
			t.Errorf("lines()[%d] = %q, want %q", i, got[i], want[i])
		}
	}
}

func TestRingUnderCapacity(t *testing.T) {
	r := newRing(10)
	r.add("only")
	if got := r.text(); got != "only" {
		t.Errorf("text() = %q, want %q", got, "only")
	}
}

// TestRingTextJoinsWithNewlines pins the separator. text() feeds the log
// viewport, so joining with anything but "\n" renders the whole install log on
// a single line. Needs >= 2 lines to be observable at all.
func TestRingTextJoinsWithNewlines(t *testing.T) {
	r := newRing(10)
	for _, s := range []string{"first", "second", "third"} {
		r.add(s)
	}
	if got, want := r.text(), "first\nsecond\nthird"; got != want {
		t.Errorf("text() = %q, want %q", got, want)
	}
}

func TestRingEmpty(t *testing.T) {
	r := newRing(10)
	if got := r.text(); got != "" {
		t.Errorf("text() = %q, want empty", got)
	}
}

