}

func TestChoiceFromEnvPopulatesAndDefaultsHostname(t *testing.T) {
	t.Setenv("HADRON_INSTALL_NONINTERACTIVE", "1")
	t.Setenv("HADRON_USER", "ada")
	t.Setenv("HADRON_PASS", "hunter2")
